-- password: single client-generated UUID identifier.
--
-- The entry id is bound into the AES-GCM associated data at encryption time,
-- i.e. before the row exists, so it has to be generated by the client.
-- The bigint IDENTITY id (assigned by the database on INSERT) becomes redundant:
-- entry_uuid takes over as the primary key and is renamed to id.
--
-- Existing rows keep their entry_uuid as the new id, so already encrypted
-- entries stay decryptable. The identity sequence is dropped with the column.

ALTER TABLE public.password DROP CONSTRAINT password_pkey;
ALTER TABLE public.password DROP COLUMN id;

ALTER TABLE public.password DROP CONSTRAINT password_entry_uuid_key;
ALTER TABLE public.password RENAME COLUMN entry_uuid TO id;
ALTER TABLE public.password ADD CONSTRAINT password_pkey PRIMARY KEY (id);
